import{_ as p,C as a,c as o,o as d,j as s,G as i,ak as c,a as r}from"./chunks/framework.D7ejh1zC.js";const H=JSON.parse('{"title":"应用协议","description":"","frontmatter":{},"headers":[],"relativePath":"module/network/应用协议.md","filePath":"concept/module/network/应用协议.md","lastUpdated":1786880804000}'),h={name:"module/network/应用协议.md"};function b(u,e,T,m,k,g){const l=a("mdInfo"),t=a("NolebaseGitContributors"),n=a("NolebaseGitChangelog");return d(),o("div",null,[e[0]||(e[0]=s("h1",{id:"应用协议",tabindex:"-1"},[r("应用协议 "),s("a",{class:"header-anchor",href:"#应用协议","aria-label":'Permalink to "应用协议"'},"​")],-1)),i(l),e[1]||(e[1]=c(`<h2 id="应用协议url" tabindex="-1">应用协议URL <a class="header-anchor" href="#应用协议url" aria-label="Permalink to &quot;应用协议URL&quot;">​</a></h2><p>URL 是统一资源定位符，用于定位互联网上的资源。</p><p>URL 是一个固定格式的字符串，包含以下信息：</p><div class="language-txt vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://www.example.com:80/index.html?id=1#t1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li>协议 <code>schema</code> ：用于指定访问资源的协议，如 <code>HTTP</code>、<code>HTTPS</code>、<code>FTP</code> 等。</li><li>主机名 <code>domain</code> ：用于指定访问资源的主机名，如 <code>www.example.com</code>。</li><li>端口号 <code>port</code> ：用于指定访问资源的端口号，如 80、443 等。</li><li>路径 <code>path</code> ：用于指定访问资源的路径，如 <code>/index.html</code>。</li><li>查询参数 <code>query</code> ：用于指定访问资源的查询参数，如 <code>?key=value</code>。</li><li>锚点 <code>hash</code> ：用于指定访问资源的锚点，如 <code>#top</code>。</li></ul><p>它表达了：从网络中哪台计算机（<code>domain</code>）的哪个程序（<code>port</code>）寻找哪个服务（<code>path</code>），并注明获取服务的具体细节（<code>path</code>），以及要用什么样的协议通信（<code>schema</code>）。</p><p>这里包含一些细节：</p><ul><li>当协议是 <code>HTTP</code> 时，端口号默认是 80，可以省略端口。</li><li>当协议是 <code>HTTPS</code> 时，端口号默认是 443，可以省略端口。</li><li><code>schema</code>、<code>domain</code>、<code>path</code> 是必须的，其他的根据具体要求填写。</li></ul><div class="danger custom-block github-alert"><p class="custom-block-title">误区</p><p>Q：在网络中看到一张图片，路径为 <code>https://www.baidu.com/img/bd_logo1.png</code>，那么这个图片是存放在百度服务器上的吗？</p><p>A：不是，URL 地址只不过从网络中某台计算机的某个程序要某个服务，程序收到 URL 地址后给什么、给不给是由后端程序来决定。它访问的是程序，而不是路径，不代表对应路径上的资源。</p><p>Q：为什么 VSCode 的插件 <code>Live Server</code> 可以通过 URL 访问本地文件？</p><p>A：因为 <code>Live Server</code> 是一个静态资源服务器，它会将本地文件映射到一个虚拟路径上，然后通过 URL 访问虚拟路径，虚拟路径会被映射到本地文件，从而实现访问本地文件的功能。它本质上是一个程序。</p></div><h2 id="应用协议http" tabindex="-1">应用协议HTTP <a class="header-anchor" href="#应用协议http" aria-label="Permalink to &quot;应用协议HTTP&quot;">​</a></h2><p>超文本传输协议是一个广泛运用于互联网的应用层协议。该协议规定两个方面的内容：</p><ul><li>传递消息的模式</li><li>传递消息的格式</li></ul><h3 id="http传递消息的模式" tabindex="-1">HTTP传递消息的模式 <a class="header-anchor" href="#http传递消息的模式" aria-label="Permalink to &quot;HTTP传递消息的模式&quot;">​</a></h3><p><img src="https://pic1.imgdb.cn/item/67dfb61e88c538a9b5c50b33.png" alt="传递消息的模式" loading="lazy"></p><p>HTTP 使用了一种极简单的消息传递模式，【请求-响应】模式。发起请求的称之为客户端，接收请求并完成响应的称之为服务器。【请求-响应】完成后，一次交互结束。</p><h3 id="http传递消息的格式" tabindex="-1">HTTP传递消息的格式 <a class="header-anchor" href="#http传递消息的格式" aria-label="Permalink to &quot;HTTP传递消息的格式&quot;">​</a></h3><blockquote><p>这里推荐一个 VSCode 插件：<code>REST Client</code>，可以直接在 VSCode 中发送 HTTP 请求，并且可以查看响应结果。</p><p><img src="https://pic1.imgdb.cn/item/67dfb88988c538a9b5c50bbe.png" alt="请求" loading="lazy"></p><p>注意：请求体是可选的，无论是否有请求体，请求体结束后都要换两行。</p></blockquote><p>HTTP 消息格式是一种纯文本的格式，文本分为三部分组成：</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-ttHTR" id="tab-bC1Bahk" checked><label data-title="get请求.http" for="tab-bC1Bahk">get请求.http</label><input type="radio" name="group-ttHTR" id="tab-SzhrxBQ"><label data-title="post请求.http" for="tab-SzhrxBQ">post请求.http</label></div><div class="blocks"><div class="language-http vp-adaptive-theme active line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求行 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GET / HTTP/1.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求头 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST: www.taobao.com</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求体 --&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求行 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">POST /api/user HTTP/1.1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求头 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HOST: study.duyiedu.com</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求体：格式一 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loginId=admin</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loginPwd=123456</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 请求体：格式二 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loginId:admin</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loginPwd:123456</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div></div></div><ol><li>请求行</li><li>请求头</li><li>请求体</li></ol><h4 id="http请求行" tabindex="-1">HTTP请求行 <a class="header-anchor" href="#http请求行" aria-label="Permalink to &quot;HTTP请求行&quot;">​</a></h4><p>请求行是 HTTP 消息的第一行，它包含了请求方法、请求路径、HTTP 版本等信息。</p><p>请求行第一个单词是请求方法，<strong>在 HTTP 协议中，请求方法仅有语义的区别</strong>，只是表达了这次请求的【愿望】。比如 GET 表示客户端想要获取一些东西，POST 表示客户端想要发送一些东西。</p><p>常见的请求方法有：</p><ul><li>GET：获取资源</li><li>POST：提交数据</li><li>PUT：更新资源</li><li>DELETE：删除资源</li></ul><p>请求行第二个单词是请求路径，它是请求的目标资源的路径。</p><p>请求行第三个单词是 HTTP 版本，它是 HTTP 协议的版本号。</p><h4 id="http请求头" tabindex="-1">HTTP请求头 <a class="header-anchor" href="#http请求头" aria-label="Permalink to &quot;HTTP请求头&quot;">​</a></h4><p>请求头是 HTTP 消息的第二部分，它包含了请求的元数据，比如请求头字段名和字段值。</p><p>请求头字段名和字段值之间使用冒号分隔，多个请求头之间使用换行分隔。</p><p>常见的请求头字段有：</p><ul><li><code>Host</code>：请求的服务器地址（必写）</li><li><code>User-Agent</code>：客户端信息</li><li><code>Accept</code>：客户端能够接收的数据类型 <code>Content-Type</code>：请求体的数据类型</li><li><code>Content-Length</code>：请求体的长度</li></ul><h4 id="http请求体" tabindex="-1">HTTP请求体 <a class="header-anchor" href="#http请求体" aria-label="Permalink to &quot;HTTP请求体&quot;">​</a></h4><p>请求体是 HTTP 消息的第三部分，它是客户端发送给服务器的数据。</p><p>请求体的格式可以是文本格式，也可以是二进制格式，由请求头 <code>Content-Type</code> 字段来决定；请求体的长度可以通过请求头中的 <code>Content-Length</code> 字段来指定。</p><p>常见格式为：</p><ul><li><code>application/x-www-form-urlencoded</code>：表单数据，键值对形式</li><li><code>application/json</code>：JSON 格式数据</li><li><code>multipart/form-data</code>：文件上传数据</li><li><code>text/plain</code>：纯文本数据</li><li><code>text/html</code>：HTML 文档数据</li><li><code>image/jpeg</code>：图片数据</li></ul><p>一般的，<code>x-www-form-urlencoded</code> 格式的表单数据只能传字符，如果要传文件（如头像图片等），只能转为 <code>base64</code> 编码后再传。这样会有一定的性能损失，所以一般文件上传使用 <code>multipart/form-data</code> 格式。</p><p>请求体的内容可以通过请求方法来指定，比如 GET 请求没有请求体，POST 请求有请求体。</p><h4 id="http响应行" tabindex="-1">HTTP响应行 <a class="header-anchor" href="#http响应行" aria-label="Permalink to &quot;HTTP响应行&quot;">​</a></h4><p>响应行是 HTTP 响应消息的第一行，它包含了 HTTP 版本、状态码和状态描述等信息。</p><p>响应行第一个单词是 HTTP 版本，表示服务器使用的 HTTP 协议版本。</p><p>响应行第二个单词是状态码，表示服务器对请求的处理结果。</p><p>常见的响应码有：</p><table tabindex="0"><thead><tr><th>分类</th><th>分类描述</th></tr></thead><tbody><tr><td>1xx</td><td>指示信息，表示请求已接收，继续处理</td></tr><tr><td>2xx</td><td>成功，表示请求已被成功接收、理解、接受</td></tr><tr><td>3xx</td><td>重定向，表示要完成请求，需要进一步操作</td></tr><tr><td>4xx</td><td>客户端错误，表示请求有语法错误或请求无法实现</td></tr><tr><td>5xx</td><td>服务器端错误，表示服务器未能实现合法的请求</td></tr></tbody></table><p>常见的状态码有：</p><ul><li>200：请求成功</li><li>301：永久重定向，浏览器遇到这个响应会本地缓存新的地址，下次请求直接用新的地址</li><li>302：临时重定向，浏览器不会缓存新的地址，每次请求都需要带上原始地址</li><li>400：客户端请求错误</li><li>401：未授权</li><li>403：禁止访问</li><li>404：未找到</li><li>500：服务器内部错误</li></ul><p>响应行第三个单词是状态描述，表示服务器对请求的处理结果的描述。</p><h4 id="http响应头" tabindex="-1">HTTP响应头 <a class="header-anchor" href="#http响应头" aria-label="Permalink to &quot;HTTP响应头&quot;">​</a></h4><p>响应头是 HTTP 响应消息的第二部分，它包含了响应的元数据，如响应的内容类型、内容长度、服务器信息等。</p><p>常见的响应头有：</p><ul><li><code>Content-Type</code>：响应体的数据类型消息格式（重要）</li><li><code>Content-Length</code>：响应体的字节长度</li><li><code>Server</code>：服务器信息</li><li><code>Date</code>：响应时间</li><li><code>Last-Modified</code>：资源最后修改时间</li><li><code>ETag</code>：资源的唯一标识符</li><li><code>Cache-Control</code>：缓存控制</li><li><code>Expires</code>：资源的过期时间</li><li><code>Set-Cookie</code>：设置 <code>Cookie</code></li><li><code>Location</code>：重定向地址</li></ul><h4 id="http响应体" tabindex="-1">HTTP响应体 <a class="header-anchor" href="#http响应体" aria-label="Permalink to &quot;HTTP响应体&quot;">​</a></h4><p>响应体是 HTTP 响应消息的第三部分，它包含了服务器返回的实际数据，如 HTML、JSON、图片等。</p>`,54)),i(t),i(n)])}const E=p(h,[["render",b]]);export{H as __pageData,E as default};
